use criterion::{BatchSize, BenchmarkId, Criterion, black_box, criterion_group, criterion_main};
use log_analyzer_workshop::{Level, Summary, analyze_reader, parse_record};
use std::io::{BufRead, Cursor};

fn classify(summary: &mut Summary, line: &[u8], filter: Option<Level>) {
    match parse_record(line) {
        Ok(record) if filter.is_none_or(|wanted| wanted == record.level) => match record.level {
            Level::Info => summary.info += 1,
            Level::Warn => summary.warn += 1,
            Level::Error => summary.error += 1,
        },
        Ok(_) => {}
        Err(_) => summary.malformed += 1,
    }
}

fn baseline(reader: impl BufRead, filter: Option<Level>) -> Summary {
    let mut reader = reader;
    let mut summary = Summary::default();
    let mut line = Vec::new();
    loop {
        line.clear();
        let read = reader
            .read_until(b'\n', &mut line)
            .expect("benchmark input is readable");
        if read == 0 {
            break;
        }
        if line.last() == Some(&b'\n') {
            line.pop();
        }
        classify(&mut summary, &line, filter);
    }
    summary
}

fn candidate(reader: impl BufRead, filter: Option<Level>) -> Summary {
    analyze_reader(reader, filter).expect("benchmark input is readable")
}

fn workload(lines: usize, malformed_every: Option<usize>) -> Vec<u8> {
    let levels = ["INFO", "WARN", "ERROR"];
    let mut input = Vec::with_capacity(lines * 32);
    for index in 0..lines {
        if malformed_every.is_some_and(|period| index % period == 0) {
            input.extend_from_slice(format!("{index} DEBUG malformed\n").as_bytes());
        } else {
            let level = levels[index % levels.len()];
            input.extend_from_slice(format!("{index} {level} message-{index}\n").as_bytes());
        }
    }
    input
}

fn workloads() -> [(String, Vec<u8>); 3] {
    [
        ("small_valid".to_owned(), workload(8, None)),
        ("mixed_malformed".to_owned(), workload(64, Some(7))),
        ("large_valid".to_owned(), workload(512, None)),
    ]
}

fn benchmark_analyzer(c: &mut Criterion) {
    let mut group = c.benchmark_group("log_analyzer");
    for (name, input) in workloads() {
        assert_eq!(
            baseline(Cursor::new(input.as_slice()), None),
            candidate(Cursor::new(input.as_slice()), None),
            "baseline and candidate must have the same result shape"
        );
        group.throughput(criterion::Throughput::Bytes(input.len() as u64));
        // setup uses borrowed input before the timed closure; teardown drops the reader afterward.
        group.bench_with_input(BenchmarkId::new("baseline", &name), &input, |b, input| {
            b.iter_batched_ref(
                || Cursor::new(input.as_slice()),
                |reader| black_box(baseline(reader, None)),
                BatchSize::SmallInput,
            );
        });
        group.bench_with_input(BenchmarkId::new("candidate", &name), &input, |b, input| {
            b.iter_batched_ref(
                || Cursor::new(input.as_slice()),
                |reader| black_box(candidate(reader, None)),
                BatchSize::SmallInput,
            );
        });
    }
    group.finish();
}

criterion_group!(benches, benchmark_analyzer);
criterion_main!(benches);
